SELECT ?s ?cls ?lbl ?tsid WHERE {
  ?s a ?cls .
  OPTIONAL { ?s rdfs:label ?lbl }
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
  FILTER (CONTAINS(STR(?cls), "Perimeter_top_ZN_2") || CONTAINS(STR(?s), "Perimeter_top_ZN_2"))
} LIMIT 50

SELECT ?s ?cls ?lbl ?tsid WHERE {
  ?s a ?cls .
  OPTIONAL { ?s rdfs:label ?lbl }
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid }
  FILTER (CONTAINS(STR(?cls), "Lighting") || CONTAINS(STR(?cls), "Electric_Power") || CONTAINS(STR(?cls), "Occupancy"))
} LIMIT 200

SELECT ?z ?lbl WHERE {
  ?z a https://brickschema.org/schema/Brick#Zone .
  OPTIONAL { ?z rdfs:label ?lbl }
} ORDER BY STR(?z)

